CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE ROLE anon NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE authenticated NOLOGIN; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE ROLE service_role NOLOGIN BYPASSRLS; EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE SCHEMA IF NOT EXISTS auth;
CREATE SCHEMA IF NOT EXISTS app;
CREATE OR REPLACE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$
  SELECT NULLIF(current_setting('request.jwt.claim.sub', true), '')::uuid
$$;
CREATE TYPE public.app_role AS ENUM ('admin','sales','production','hr','customer','employee','accountant','vendor');
CREATE TYPE public.voucher_type AS ENUM ('sales','purchase','receipt','payment','contra','journal','debit_note','credit_note','stock_journal');
CREATE TYPE public.ledger_nature AS ENUM ('assets','liabilities','income','expenses');
CREATE TYPE public.invoice_status AS ENUM ('draft','unpaid','partial','paid','cancelled');
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,role public.app_role NOT NULL,UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE OR REPLACE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TABLE public.parties(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,user_id uuid,owner_id uuid,credit_limit numeric NOT NULL DEFAULT 0,opening_balance numeric NOT NULL DEFAULT 0,current_balance numeric NOT NULL DEFAULT 0);
CREATE TABLE public.suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,user_id uuid,opening_balance numeric NOT NULL DEFAULT 0,current_balance numeric NOT NULL DEFAULT 0);
CREATE TABLE public.ledger_groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,nature public.ledger_nature NOT NULL,affects_gross_profit boolean NOT NULL DEFAULT false);
CREATE TABLE public.ledger_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,group_id uuid NOT NULL REFERENCES public.ledger_groups(id),opening_balance numeric NOT NULL DEFAULT 0,opening_balance_type text NOT NULL DEFAULT 'dr',mapped_party_id uuid REFERENCES public.parties(id),mapped_supplier_id uuid REFERENCES public.suppliers(id),is_active boolean NOT NULL DEFAULT true);
CREATE TABLE public.cost_centers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL);
CREATE TABLE public.financial_years(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,is_current boolean NOT NULL DEFAULT false,is_locked boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.voucher_number_series(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),voucher_type public.voucher_type NOT NULL UNIQUE,prefix text NOT NULL DEFAULT '',suffix text NOT NULL DEFAULT '',next_number integer NOT NULL DEFAULT 1,width integer NOT NULL DEFAULT 4,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.vouchers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),voucher_number text NOT NULL,voucher_type public.voucher_type NOT NULL,voucher_date date NOT NULL DEFAULT current_date,narration text,reference text,source_table text,source_id uuid,is_locked boolean NOT NULL DEFAULT false,financial_year_id uuid REFERENCES public.financial_years(id),created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),currency_code text DEFAULT 'INR',exchange_rate numeric NOT NULL DEFAULT 1,UNIQUE(voucher_type,voucher_number),UNIQUE(source_table,source_id));
CREATE TABLE public.voucher_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),voucher_id uuid NOT NULL REFERENCES public.vouchers(id) ON DELETE CASCADE,ledger_account_id uuid NOT NULL REFERENCES public.ledger_accounts(id),cost_center_id uuid REFERENCES public.cost_centers(id),debit numeric NOT NULL DEFAULT 0,credit numeric NOT NULL DEFAULT 0,narration text,line_order integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),invoice_number text NOT NULL UNIQUE,party_id uuid NOT NULL REFERENCES public.parties(id),invoice_date date NOT NULL,total_amount numeric NOT NULL,subtotal numeric NOT NULL,tax_amount numeric NOT NULL DEFAULT 0,due_date date,dispatch_state_code text,supplier_gstin text,status public.invoice_status NOT NULL DEFAULT 'unpaid',paid_amount numeric NOT NULL DEFAULT 0,created_by uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.purchase_bills(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bill_number text NOT NULL,supplier_id uuid REFERENCES public.suppliers(id),bill_date date NOT NULL,total_amount numeric NOT NULL,created_by uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO authenticated; GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
CREATE OR REPLACE FUNCTION public.get_or_create_party_ledger(_party_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x uuid; n text; g uuid; BEGIN SELECT id INTO x FROM ledger_accounts WHERE mapped_party_id=_party_id; IF x IS NOT NULL THEN RETURN x; END IF; SELECT name INTO n FROM parties WHERE id=_party_id; SELECT id INTO g FROM ledger_groups WHERE name='Sundry Debtors'; INSERT INTO ledger_accounts(name,group_id,mapped_party_id) VALUES(n,g,_party_id) RETURNING id INTO x; RETURN x; END $$;
CREATE OR REPLACE FUNCTION public.get_or_create_supplier_ledger(_supplier_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x uuid; n text; g uuid; BEGIN SELECT id INTO x FROM ledger_accounts WHERE mapped_supplier_id=_supplier_id; IF x IS NOT NULL THEN RETURN x; END IF; SELECT name INTO n FROM suppliers WHERE id=_supplier_id; SELECT id INTO g FROM ledger_groups WHERE name='Sundry Creditors'; INSERT INTO ledger_accounts(name,group_id,mapped_supplier_id) VALUES(n,g,_supplier_id) RETURNING id INTO x; RETURN x; END $$;
INSERT INTO public.user_roles(user_id,role) VALUES ('00000000-0000-0000-0000-000000000001','admin'),('00000000-0000-0000-0000-000000000001','accountant'),('00000000-0000-0000-0000-000000000002','sales'),('00000000-0000-0000-0000-000000000003','production');
INSERT INTO public.ledger_groups(name,nature) VALUES ('Assets','assets'),('Income','income'),('Expenses','expenses'),('Liabilities','liabilities'),('Sundry Debtors','assets'),('Sundry Creditors','liabilities');
INSERT INTO public.ledger_accounts(name,group_id) SELECT x.name,g.id FROM (VALUES ('Cash','Assets'),('Bank','Assets'),('Sales','Income'),('Purchases','Expenses'),('Output CGST','Liabilities'),('Output SGST','Liabilities'),('Output IGST','Liabilities')) x(name,grp) JOIN ledger_groups g ON g.name=x.grp;
INSERT INTO public.parties(id,name) VALUES ('10000000-0000-0000-0000-000000000001','Fixture Customer');
INSERT INTO public.suppliers(id,name) VALUES ('20000000-0000-0000-0000-000000000001','Fixture Supplier');
SELECT public.get_or_create_party_ledger('10000000-0000-0000-0000-000000000001');
SELECT public.get_or_create_supplier_ledger('20000000-0000-0000-0000-000000000001');
INSERT INTO public.financial_years(id,name,start_date,end_date,is_current,is_locked) VALUES ('30000000-0000-0000-0000-000000000001','2025-26','2025-04-01','2026-03-31',false,true),('30000000-0000-0000-0000-000000000002','2026-27','2026-04-01','2027-03-31',true,false);
INSERT INTO public.voucher_number_series(voucher_type,prefix) SELECT v,CASE v WHEN 'sales' THEN 'SAL/' WHEN 'purchase' THEN 'PUR/' WHEN 'receipt' THEN 'RCP/' WHEN 'payment' THEN 'PAY/' WHEN 'contra' THEN 'CON/' WHEN 'journal' THEN 'JV/' WHEN 'debit_note' THEN 'DN/' WHEN 'credit_note' THEN 'CN/' ELSE 'STK/' END FROM unnest(enum_range(NULL::public.voucher_type)) v;
